mapper.select:
SELECT co.order_id AS orderId, co.channel_order_no AS channelOrderNo, co.order_channel AS orderChannel, co.ordered_at AS orderedAt, co.receiver_name AS receiverName, co.invoice_no AS invoiceNo, co.shipped_at AS shippedAt, ( SELECT coi.product_name_snapshot FROM channel_order_item coi WHERE coi.order_id = co.order_id LIMIT 1 ) AS firstItemName, ( SELECT COUNT(*) FROM channel_order_item coi2 WHERE coi2.order_id = co.order_id ) AS itemCount FROM channel_order co
co.seller_id = #{params.sellerId}
AND co.order_channel = #{params.channel}
AND ( co.channel_order_no LIKE CONCAT('%', #{params.search}, '%') OR co.receiver_name LIKE CONCAT('%', #{params.search}, '%') )
ORDER BY co.ordered_at DESC LIMIT #{params.size} OFFSET #{params.offset}
